{"command": "cat <<'EOF' > /app/alpine-serial.expect
#!/usr/bin/expect -f
set timeout 600
set iso "/app/alpine.iso"
set disk "/app/alpine-disk.qcow2"
set prompt "localhost:~# "
set rootprompt "localhost:~# "
spawn qemu-system-x86_64 \
  -m 1024 \
  -smp 2 \
  -boot d \
  -cdrom $iso \
  -drive file=$disk,format=qcow2 \
  -netdev user,id=net0,hostfwd=tcp::2222-:22 \
  -device e1000,netdev=net0 \
  -nographic \
  -serial mon:stdio

# Wait for login prompt
expect {
  -re "login:" { send "root\r" }
  timeout { send_user "Timeout waiting for login prompt\n"; exit 1 }
}
# Wait for shell prompt
expect {
  -re "# " { }
  timeout { send_user "Timeout waiting for shell prompt\n"; exit 1 }
}

# Set root password
send "passwd\r"
expect {
  -re "New password:" { send "password123\r" }
  timeout { send_user "Timeout waiting for new password\n"; exit 1 }
}
expect {
  -re "Retype password:" { send "password123\r" }
  timeout { send_user "Timeout waiting for retype password\n"; exit 1 }
}
expect {
  -re "password updated successfully" { }
  -re "# " { }
  timeout { send_user "Timeout waiting for passwd completion\n"; exit 1 }
}

# Install and start openssh
send "setup-ssh -c openssh\r"
expect {
  -re "# " { }
  timeout { send_user "Timeout waiting for setup-ssh\n"; exit 1 }
}

# Ensure sshd running
send "rc-service sshd restart\r"
expect {
  -re "# " { }
  timeout { send_user "Timeout waiting for sshd restart\n"; exit 1 }
}

# Ensure sshd enabled on boot (optional)
send "rc-update add sshd default\r"
expect {
  -re "# " { }
  timeout { send_user "Timeout waiting for rc-update\n"; exit 1 }
}

# Keep session open
interact
EOF
chmod +x /app/alpine-serial.expect
"}

