import os, socket, struct
# Parse /proc/net/tcp and find entry for port 2222 (0x08AE) or 5555 (0x15B3)
ports = {0x08AE, 0x15B3}
for path in ['/proc/net/tcp']:
    with open(path) as f:
        next(f)
        for line in f:
            parts = line.split()
            local = parts[1]
            local_ip_hex, local_port_hex = local.split(':')
            port = int(local_port_hex, 16)
            if port in ports:
                inode = parts[9]
                print('found', port, 'inode', inode)
                # find pid
                for pid in filter(str.isdigit, os.listdir('/proc')):
                    fd_dir = f'/proc/{pid}/fd'
                    if not os.path.isdir(fd_dir):
                        continue
                    try:
                        for fd in os.listdir(fd_dir):
                            try:
                                target = os.readlink(os.path.join(fd_dir, fd))
                            except Exception:
                                continue
                            if target.startswith('socket:[') and target[8:-1] == inode:
                                cmdline = open(f'/proc/{pid}/cmdline','rb').read().replace(b'\x00', b' ').decode('utf-8','ignore')
                                print(' pid', pid, 'cmd', cmdline[:200])
                                raise SystemExit
                    except FileNotFoundError:
                        continue
PY"}

